/// <summary>
/// class of METRetroDiscountDiscountClaimPost
/// </summary>
internal final class METRetroDiscountDiscountClaimPost
{
    private RetailPeriodicDiscount  retailPeriodicDiscount;
    private List                    transList;

    private GUPDiscountClaimHelper  discountClaimHelper;

    private CustInvoiceId           invoiceId;
    private TransDate               invoiceDate;
    private CustInvoiceAccount      invoiceAccount;

}

Method.Source:
    /// <summary>
    /// New
    /// </summary>
    /// <param name = "_trans">Transaction</param>
    protected internal void new(METRetroDiscountSalesInvoiceTransaction _trans)
    {
        this.retailPeriodicDiscount = RetailPeriodicDiscount::findByOfferId(_trans.OfferId);
        this.transList = new List(Types::Int64);
        this.invoiceId = _trans.InvoiceId;
        this.invoiceDate = _trans.InvoiceDate;
        this.invoiceAccount = _trans.InvoiceAccount;

        this.addTransToList(_trans);

        discountClaimHelper = new GUPDiscountClaimHelper();
    }

/// <summary>
/// Add trans to List
/// </summary>
/// <param name = "_trans">Transaction</param>
internal void addTransToList(METRetroDiscountSalesInvoiceTransaction _trans)
{
    transList.addEnd(_trans.RecId);
}

    /// <summary>
    /// postDiscountClaim
    /// </summary>
    internal void postDiscountClaim()
    {
        this.createRetroDiscountClaimAndAccrualJournal();

        discountClaimHelper.setPostLinesParameters(
                                        null,
                                        CustInvoiceJour::findFromCustTrans(invoiceId, invoiceDate, invoiceAccount).LedgerVoucher,
                                        invoiceDate);

        discountClaimHelper.postDiscountClaimAccrualJournal();
    }

    /// <summary>
    /// Create Journal
    /// </summary>
    private void createRetroDiscountClaimAndAccrualJournal()
    {
        RetailSalesDiscountLine                 retailSalesDiscountLine;
        RetailDiscountLineOffer                 retailDiscountLineOffer;
        METRetroDiscountSalesInvoiceTransaction trans;
        SalesLine   salesLine;

        ListEnumerator enumerator = this.transList.getEnumerator();

        while (enumerator.moveNext())
        {
            trans = METRetroDiscountSalesInvoiceTransaction::find(enumerator.current(), true);
            
            if (trans.RetroDiscountAmount == 0)
            {
                continue;
            }

            salesLine = SalesLine::findInventTransId(trans.InventTransId);

            retailSalesDiscountLine.clear();
            retailSalesDiscountLine.PeriodicDiscountOfferId = trans.OfferId;
            retailSalesDiscountLine.RefTableId = tableNum(RetailPeriodicDiscountLine);
            retailSalesDiscountLine.RefRecId = trans.DiscountLineRefRecId;

            retailDiscountLineOffer = RetailPeriodicDiscountLine::find(trans.DiscountLineRefRecId) as RetailDiscountLineOffer;

            discountClaimHelper.setDiscountPostParameters(
                                        trans.InvoiceQty,
                                        trans.ItemId,
                                        salesLine.InventDimId,
                                        trans.InvoiceId,
                                        salesLine);

            discountClaimHelper.distributeDiscountClaim(retailSalesDiscountLine, retailPeriodicDiscount, retailDiscountLineOffer, trans.RetroDiscountAmount);
        }
    }
